 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row if x != 0)
    color = min(counts, key=counts.get)
    # The rare colored object is the stamp pattern.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(comp)
    shape = max(components, key=len)
    minr = min(r for r,c in shape)
    minc = min(c for r,c in shape)
    offsets = [(r-minr, c-minc) for r,c in shape]
    oh = max(r for r,c in offsets) + 1
    ow = max(c for r,c in offsets) + 1
    out = [row[:] for row in grid]
    for top in range(h-oh+1):
        for left in range(w-ow+1):
            cells = [(top+dr,left+dc) for dr,dc in offsets]
            if all(grid[r][c] == 0 for r,c in cells):
                for r,c in cells:
                    out[r][c] = color
    return out
